import{_ as s,o as i,c as a,a2 as n}from"./chunks/framework.B8TleWq7.js";const u=JSON.parse('{"title":"Console (client)","description":"","frontmatter":{"title":"Console (client)","outline":[2,3]},"headers":[],"relativePath":"api/client-console.md","filePath":"api/client-console.md"}'),t={name:"api/client-console.md"};function o(l,e,r,d,h,c){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="console-client" tabindex="-1">Console (client) <a class="header-anchor" href="#console-client" aria-label="Permalink to &quot;Console (client)&quot;">​</a></h1><p>Opens the Cmdr console window for admins.</p><p><span class="keel-badge keel-badge-client">Client</span> <span class="keel-src"><code>src/ReplicatedStorage/Keel/Client/Console.luau</code></span></p><div class="language-luau vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">luau</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Console </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ReplicatedStorage.Keel.Client.Console)</span></span></code></pre></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The server half (KeelServer/Console) owns the commands and who may run them; this half only shows the window. It turns the window on while the server says this player is an admin (Account.Admin), and off otherwise. Hiding the window is a convenience: the real check is on the server, so a modified client gains nothing.</p><ul><li><strong>Owns:</strong> the activation key and the enabled state of Cmdr&#39;s client.</li><li><strong>Called by:</strong> Client/Main (Console.Start, after the client is ready).</li><li><strong>Fires:</strong> nothing.</li></ul><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language-luau vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">luau</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- once. Press F2 to open or close the window (admins only)</span></span></code></pre></div><p>Cmdr&#39;s client arrives in ReplicatedStorage (CmdrClient) when the server&#39;s Console service boots. If it is missing after a few seconds the console is skipped with a warning; nothing else depends on it.</p><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h2><h3 id="console-start" tabindex="-1">Console.Start <a class="header-anchor" href="#console-start" aria-label="Permalink to &quot;Console.Start {#console-start}&quot;">​</a></h3><div class="language-luau vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">luau</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Start</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p>Waits for Cmdr&#39;s client, binds <strong>F2</strong> to its window, and enables the window only while <code>Account.Admin</code> is true (read through State). <code>Client/Main</code> calls it once, after <code>Net.ClientReady()</code>. It is not a Loader module.</p><p>If Cmdr&#39;s client is still missing after a few seconds, the console is skipped with a warning; nothing else depends on it.</p><p>On a live server only admins (the UserIds in <code>Server/Defs/Admins</code>) get the window; in Studio everyone does. The server enforces this regardless, with a Cmdr <code>BeforeRun</code> hook. See <a href="/Keel-Docs/guides/console">Console</a>.</p>',16)])])}const g=s(t,[["render",o]]);export{u as __pageData,g as default};
